:root {
  --ink: #20233b;
  --paper: #fffdf7;
  --plum: #4b285f;
  --coral: #f26b5e;
  --gold: #f7c64b;
  --mint: #c9f0d3;
  --line: #e8dfd1;
}

.pickup-card {
  width: 480px;
  overflow: hidden;
  border: 2px solid var(--ink);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 18px 14px;
  background: var(--plum);
  color: var(--paper);
}

.title-block {
  min-width: 0;
}

.eyebrow {
  margin: 0 0 4px;
  color: var(--gold);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1.1px;
}

.card-title {
  margin: 0;
  font-size: 22px;
  line-height: 1.1;
  font-weight: 800;
}

.status {
  margin: 1px 0 0;
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--mint);
  color: var(--plum);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.8px;
}

.order-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  padding: 14px 18px;
}

.item {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 11px;
}

.item-icon {
  display: grid;
  flex: 0 0 36px;
  width: 36px;
  height: 36px;
  place-items: center;
  margin: 0;
  border-radius: 10px;
  background: var(--gold);
  font-size: 20px;
}

.item-copy {
  min-width: 0;
}

.item-name {
  margin: 0 0 2px;
  font-size: 14px;
  line-height: 1.15;
  font-weight: 800;
}

.item-note {
  margin: 0;
  color: var(--plum);
  font-size: 11px;
  line-height: 1.25;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 12px 18px;
  border-top: 1px solid var(--line);
  background: var(--mint);
}

.pickup-time {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.time-label {
  margin: 0;
  color: var(--plum);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.time-value {
  margin: 0;
  font-size: 18px;
  line-height: 1;
  font-weight: 900;
}

.collect {
  padding: 9px 13px;
  border: 2px solid var(--ink);
  border-radius: 9px;
  background: var(--coral);
  color: var(--paper);
  font-size: 13px;
  font-weight: 800;
}
